const items = $input.all();
const results = [];

for (const item of items) {
  const fileName = item.binary?.data?.fileName || '';
  const mimeType = item.binary?.data?.mimeType || '';

  let fileType = 'unknown';
  let processor = 'manual';

  if (fileName.toLowerCase().endsWith('.pdf') || mimeType.includes('pdf')) {
    fileType = 'pdf';
    processor = 'pdf-extractor';
  } else if (fileName.toLowerCase().endsWith('.csv') || mimeType.includes('csv')) {
    fileType = 'csv';
    processor = 'csv-parser';
  } else if (fileName.toLowerCase().match(/\.(xlsx?|xls)$/) || mimeType.includes('spreadsheet')) {
    fileType = 'excel';
    processor = 'excel-parser';
  }

  results.push({
    ...item,
    json: {
      ...item.json,
      fileType,
      processor,
      fileName,
      mimeType
    }
  });
}

return results;

const items = $input.all();
const standardized = [];

for (const item of items) {
  const data = item.json;

  // Standardize date formats to YYYY-MM-DD
  const standardizeDate = (dateStr) => {
    if (!dateStr) return null;

    // Handle various Mexican date formats
    const patterns = [
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/, // DD/MM/YYYY
      /^(\d{4})-(\d{1,2})-(\d{1,2})$/, // YYYY-MM-DD
      /^(\d{1,2})-(\d{1,2})-(\d{4})$/, // DD-MM-YYYY
    ];

    for (const pattern of patterns) {
      const match = dateStr.match(pattern);
      if (match) {
        const [, p1, p2, p3] = match;
        if (p3.length === 4) { // Year is last
          return `${p3}-${p2.padStart(2, '0')}-${p1.padStart(2, '0')}`;
        } else { // Year is first
          return `${p1}-${p2.padStart(2, '0')}-${p3.padStart(2, '0')}`;
        }
      }
    }
    return dateStr;
  };

  // Standardize amount to numeric
  const standardizeAmount = (amountStr) => {
    if (!amountStr) return 0;
    return parseFloat(amountStr.toString().replace(/[,$]/g, '')) || 0;
  };

  const standardizedTransaction = {
    id: data.id || `${Date.now()}-${Math.random()}`,
    date: standardizeDate(data.date || data.fecha || data.Date),
    description: data.description || data.descripcion || data.concepto || data.Description || '',
    amount: standardizeAmount(data.amount || data.monto || data.importe || data.Amount),
    balance: standardizeAmount(data.balance || data.saldo || data.Balance),
    reference: data.reference || data.referencia || data.Reference || '',
    accountNumber: data.accountNumber || data.cuenta || data.Account || '',
    bankName: data.bankName || data.banco || data.Bank || '',
    currency: data.currency || 'MXN',
    type: data.type || (data.amount > 0 ? 'credit' : 'debit'),
    originalData: data
  };

  standardized.push({ json: standardizedTransaction });
}

return standardized;

// Advanced matching algorithm for bank reconciliation
const bankTransactions = $input.first().json.bankTransactions || [];
const internalRecords = $input.first().json.internalRecords || [];

const matches = [];
const unmatchedBank = [];
const unmatchedInternal = [...internalRecords];

// Matching criteria weights
const weights = {
  exactAmount: 40,
  exactDate: 30,
  similarDescription: 20,
  closeDate: 10 // within 3 days
};

const calculateSimilarity = (bankTxn, internalTxn) => {
  let score = 0;

  // Exact amount match
  if (Math.abs(bankTxn.amount - internalTxn.amount) < 0.01) {
    score += weights.exactAmount;
  }

  // Date matching
  const bankDate = new Date(bankTxn.date);
  const internalDate = new Date(internalTxn.transaction_date);
  const daysDiff = Math.abs(bankDate - internalDate) / (1000 * 60 * 60 * 24);

  if (daysDiff === 0) {
    score += weights.exactDate;
  } else if (daysDiff <= 3) {
    score += weights.closeDate;
  }

  // Description similarity (simple word matching)
  const bankWords = (bankTxn.description || '').toLowerCase().split(/\s+/);
  const internalWords = (internalTxn.description || '').toLowerCase().split(/\s+/);
  const commonWords = bankWords.filter(word => internalWords.includes(word));

  if (commonWords.length > 0) {
    score += (commonWords.length / Math.max(bankWords.length, internalWords.length)) * weights.similarDescription;
  }

  return score;
};

for (const bankTxn of bankTransactions) {
  let bestMatch = null;
  let bestScore = 0;
  let bestIndex = -1;

  for (let i = 0; i < unmatchedInternal.length; i++) {
    const internalTxn = unmatchedInternal[i];
    const score = calculateSimilarity(bankTxn, internalTxn);

    if (score > bestScore && score >= 50) { // Minimum 50% confidence
      bestMatch = internalTxn;
      bestScore = score;
      bestIndex = i;
    }
  }

  if (bestMatch) {
    matches.push({
      bankTransaction: bankTxn,
      internalTransaction: bestMatch,
      matchScore: bestScore,
      status: 'matched',
      matchType: bestScore >= 70 ? 'high_confidence' : 'medium_confidence'
    });
    unmatchedInternal.splice(bestIndex, 1);
  } else {
    unmatchedBank.push({
      bankTransaction: bankTxn,
      status: 'unmatched_bank',
      reason: 'no_internal_match_found'
    });
  }
}

// Add remaining unmatched internal transactions
const unmatchedInternalFormatted = unmatchedInternal.map(txn => ({
  internalTransaction: txn,
  status: 'unmatched_internal',
  reason: 'no_bank_match_found'
}));

return [
  {
    json: {
      summary: {
        totalBankTransactions: bankTransactions.length,
        totalInternalRecords: internalRecords.length,
        matchedCount: matches.length,
        unmatchedBankCount: unmatchedBank.length,
        unmatchedInternalCount: unmatchedInternalFormatted.length,
        reconciliationRate: (matches.length / Math.max(bankTransactions.length, 1)) * 100
      },
      matches,
      discrepancies: {
        unmatchedBank,
        unmatchedInternal: unmatchedInternalFormatted
      },
      processedAt: new Date().toISOString()
    }
  }
];

const reconciliationData = $input.first().json;
const { matches, discrepancies, summary } = reconciliationData;

// Analyze discrepancy patterns
const analysis = {
  criticalIssues: [],
  warnings: [],
  recommendations: [],
  riskLevel: 'low'
};

// Check for large unmatched amounts
const largeUnmatchedThreshold = 10000; // MXN
const unmatchedBankTotal = discrepancies.unmatchedBank.reduce((sum, item) => 
  sum + Math.abs(item.bankTransaction.amount), 0);
const unmatchedInternalTotal = discrepancies.unmatchedInternal.reduce((sum, item) => 
  sum + Math.abs(item.internalTransaction.amount), 0);

if (unmatchedBankTotal > largeUnmatchedThreshold) {
  analysis.criticalIssues.push({
    type: 'large_unmatched_bank_amount',
    amount: unmatchedBankTotal,
    message: `Transacciones bancarias sin conciliar por $${unmatchedBankTotal.toLocaleString('es-MX')} MXN`
  });
  analysis.riskLevel = 'high';
}

if (unmatchedInternalTotal > largeUnmatchedThreshold) {
  analysis.criticalIssues.push({
    type: 'large_unmatched_internal_amount',
    amount: unmatchedInternalTotal,
    message: `Registros internos sin conciliar por $${unmatchedInternalTotal.toLocaleString('es-MX')} MXN`
  });
  analysis.riskLevel = 'high';
}

// Check reconciliation rate
if (summary.reconciliationRate < 80) {
  analysis.warnings.push({
    type: 'low_reconciliation_rate',
    rate: summary.reconciliationRate,
    message: `Tasa de conciliación baja: ${summary.reconciliationRate.toFixed(1)}%`
  });
  if (analysis.riskLevel === 'low') analysis.riskLevel = 'medium';
}

// Check for duplicate patterns
const duplicateCheck = {};
discrepancies.unmatchedBank.forEach(item => {
  const key = `${item.bankTransaction.amount}_${item.bankTransaction.date}`;
  duplicateCheck[key] = (duplicateCheck[key] || 0) + 1;
});

Object.entries(duplicateCheck).forEach(([key, count]) => {
  if (count > 1) {
    analysis.warnings.push({
      type: 'potential_duplicates',
      count,
      message: `Posibles transacciones duplicadas detectadas: ${count} ocurrencias`
    });
  }
});

// Generate recommendations
if (discrepancies.unmatchedBank.length > 0) {
  analysis.recommendations.push('Revisar transacciones bancarias no conciliadas manualmente');
}
if (discrepancies.unmatchedInternal.length > 0) {
  analysis.recommendations.push('Verificar registros internos faltantes en el estado bancario');
}
if (summary.reconciliationRate < 90) {
  analysis.recommendations.push('Mejorar criterios de coincidencia de transacciones');
}

return [{
  json: {
    ...reconciliationData,
    analysis,
    processedAt: new Date().toISOString()
  }
}];

